  function renderInput(t){
    const inputArea=$('#inputArea');
    if(t.textMode){
      let html='';
      if(t.textMode==='json') html=optionField('JSON input','textInput','textarea','{\n  "hello": "world"\n}',{full:true,placeholder:'Paste JSON here'});
      if(t.textMode==='text') html=optionField('Text input','textInput','textarea','',{full:true,placeholder:'Paste or type text here…'});
      if(t.textMode==='two-text') html=`<div class="option-grid">${optionField('Original text','textA','textarea','',{full:true,placeholder:'Paste original text here'})}${optionField('Updated text','textB','textarea','',{full:true,placeholder:'Paste updated text here'})}</div>`;
      inputArea.innerHTML=`<div class="text-input-area">${html}</div>`;
      selectedFiles=[]; updateFileCount();
      return;
    }
    if(t.action==='favicon'&&t.noFile){inputArea.innerHTML='<div class="tool-note">No image required. Enter a character and colors below to create a favicon PNG.</div>';selectedFiles=[];updateFileCount();return;}
    inputArea.innerHTML=`<label class="drop-zone" id="dropZone"><input id="fileInput" type="file" accept="${esc(t.accept||'*/*')}" ${t.multi?'multiple':''}><div class="drop-icon">⇧</div><h3>Drop ${t.multi?'files':'a file'} here or <span class="browse-text">browse</span></h3><p>${t.multi?'Select multiple files for batch processing.':'Select one file to get started.'} Processing happens in your browser where supported.</p><p id="limitText">${esc(t.accept||'Most file types')}</p></label><div class="selected-files" id="selectedFiles"></div>`;
    selectedFiles=[];updateFileCount();
    const zone=$('#dropZone'), fileInput=$('#fileInput');
    zone.addEventListener('click',e=>{if(e.target!==fileInput)fileInput.click();});
    fileInput.addEventListener('change',e=>setFiles([...e.target.files]));
    zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragging');});
    zone.addEventListener('dragleave',()=>zone.classList.remove('dragging'));
    zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragging');setFiles([...e.dataTransfer.files]);});
  }
  function setFiles(files){
    if(!activeTool)return;
    const max=25; selectedFiles=activeTool.multi?files.slice(0,max):files.slice(0,1);
    if(files.length>max)toast('Maksimal 25 file per batch. File sisanya tidak dipilih.');
    const total=selectedFiles.reduce((n,f)=>n+f.size,0);
    if(total>120*1024*1024){selectedFiles=[];toast('Total file lebih dari batas 120 MB untuk satu batch.');}
    renderSelectedFiles();updateFileCount();
  }
  function renderSelectedFiles(){const box=$('#selectedFiles');if(!box)return;box.innerHTML=selectedFiles.map((f,i)=>`<div class="selected-file"><span class="file-badge">${esc((f.name.split('.').pop()||'FILE').slice(0,4).toUpperCase())}</span><div class="selected-file-info"><strong>${esc(f.name)}</strong><small>${Core.humanSize(f.size)} · ${esc(f.type||'Type unknown')}</small></div><button class="remove-file" data-remove-file="${i}" aria-label="Remove file">×</button></div>`).join('');}
  function updateFileCount(){$('#fileCountLabel').textContent=selectedFiles.length?`${selectedFiles.length} file${selectedFiles.length===1?'':'s'} selected`:'';}
  function openTool(id){const t=byId.get(id);if(!t)return;activeTool=t;outputs=[];$('#modalIcon').textContent=iconFor(t);$('#modalTitle').textContent=t.name;$('#modalDescription').textContent=t.desc;$('#toolNotice').classList.add('hidden');$('#toolNotice').textContent='';$('#optionArea').innerHTML=`<div class="option-grid">${getOptionsHTML(t)}</div>`;$('#outputArea').classList.add('hidden');$('#outputContent').innerHTML='';$('#progressWrap').classList.add('hidden');$('#runTool').disabled=false;$('#runTool').innerHTML='<span>Run tool</span><span aria-hidden="true">→</span>';renderInput(t);$('#toolModal').classList.remove('hidden');document.body.style.overflow='hidden';$('#runTool').focus();recordActivity(t,'Opened tool','Opened');}
  function closeTool(){ $('#toolModal').classList.add('hidden');document.body.style.overflow='';activeTool=null;selectedFiles=[];outputs=[]; }
  function getOpt(name, fallback=''){const el=$(`[data-opt="${name}"]`);return el?el.value:fallback;}
  function setNotice(message,kind='info'){const el=$('#toolNotice');el.textContent=message;el.className='tool-note'+(kind==='warning'?' warning':kind==='error'?' error':'');}
  function progress(pct,text){$('#progressWrap').classList.remove('hidden');$('#progressText').textContent=text||'Processing…';$('#progressPercent').textContent=`${Math.max(0,Math.min(100,Math.round(pct)))}%`;$('#progressBar').style.width=`${Math.max(0,Math.min(100,pct))}%`;}
  function resetProgress(){$('#progressWrap').classList.add('hidden');$('#progressBar').style.width='0%';}
  function addOutput(name,blob,description=''){const safe=Core.sanitizeFilename(name);outputs.push({name:safe,blob,description,url:URL.createObjectURL(blob)});return outputs[outputs.length-1];}
  function showResults(message, warnings=[]){const area=$('#outputArea');area.classList.remove('hidden');const content=$('#outputContent');let html=message?`<div class="result-message">${esc(message)}</div>`:'';for(const w of warnings)html+=`<div class="result-warning">${esc(w)}</div>`;html+='<div class="output-links">'+outputs.map((o,i)=>`<div class="output-link"><span class="out-icon">⇩</span><div class="out-info"><strong>${esc(o.name)}</strong><small>${esc(o.description||Core.humanSize(o.blob.size))}</small></div><button class="download-button" data-download-output="${i}">Download</button></div>`).join('')+'</div>';content.innerHTML=html;content.scrollIntoView({behavior:'smooth',block:'nearest'});}
  function downloadBlob(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=Core.sanitizeFilename(name);document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
