  async function loadScript(src, testGlobal){if(testGlobal&&window[testGlobal])return window[testGlobal];if(!window.__filekitScripts)window.__filekitScripts={};if(window.__filekitScripts[src])return window.__filekitScripts[src];window.__filekitScripts[src]=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.async=true;s.onload=()=>testGlobal&&!window[testGlobal]?reject(new Error(`Library loaded but ${testGlobal} is missing`)):resolve(testGlobal?window[testGlobal]:true);s.onerror=()=>reject(new Error('Tidak dapat memuat library eksternal. Periksa koneksi internet, pemblokir konten, atau CDN.'));document.head.appendChild(s);});return window.__filekitScripts[src];}
