      if(t.action==='image-upscale')opts={factor:Number(getOpt('factor','2'))};
      if(t.action==='image-background')opts={background:getOpt('color','#ffffff')};
      if(t.action==='image-watermark')opts={watermark:getOpt('watermark','FileKit'),opacity:Number(getOpt('opacity','35')),position:getOpt('position','bottom-right')};
